//! Unicode property lookups for the regex escapes `\p{..}` and `\P{..}` (D1500), over the
//! tables in `props.rs` (generated by `scripts/gen-unicode.py`).
//!
//! Names are matched exactly (no loose matching), with the aliases ECMA-262 allows:
//! `General_Category`/`gc`, `Script`/`sc` and `Script_Extensions`/`scx` with a value, or a
//! lone General_Category value, binary property or (in `v` mode) property of strings.
use crate::PushOut;

use alloc::vec::Vec;

use super::props::{
    BINARY, DATA, GC_RUNS, GENERAL_CATEGORY, GENERAL_CATEGORY_GROUPS, SCRIPTS, SCX_EXPLICIT,
    STRINGS,
};

/// Why a lookup failed; the messages are QuickJS's.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum PropertyError {
    Name,
    Script,
    GeneralCategory,
}

impl PropertyError {
    pub fn message(self) -> &'static str {
        match self {
            PropertyError::Name => "unknown unicode property name",
            PropertyError::Script => "unknown unicode script",
            PropertyError::GeneralCategory => "unknown unicode general category",
        }
    }
}

/// The code points (sorted, disjoint inclusive ranges) and, for properties of strings,
/// the sequences of two or more code points.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct Property {
    pub ranges: Vec<(u32, u32)>,
    pub strings: Vec<Vec<u32>>,
}

/// Looks up `\p{name}` (`value` empty) or `\p{name=value}`, as qjs does: `\p{Script}` is
/// an unknown script, `\p{Lu=}` is `\p{Lu}`. Properties of strings are only found with
/// `strings`.
pub fn lookup(name: &str, value: &str, strings: bool) -> Result<Property, PropertyError> {
    let set = |ranges| Property {
        ranges,
        strings: Vec::new(),
    };
    match name {
        "Script" | "sc" | "Script_Extensions" | "scx" => {
            let ext = name.starts_with("Script_") || name == "scx";
            script(value, ext).map(set).ok_or(PropertyError::Script)
        }
        "General_Category" | "gc" => general_category(value)
            .map(set)
            .ok_or(PropertyError::GeneralCategory),
        _ if !value.is_empty() => Err(PropertyError::Name),
        _ => {
            if let Some(r) = general_category(name) {
                return Ok(set(r));
            }
            if let Some(r) = binary(name) {
                return Ok(set(r));
            }
            if strings && let Some(p) = string_property(name) {
                return Ok(p);
            }
            Err(PropertyError::Name)
        }
    }
}

fn has_name(names: &str, name: &str) -> bool {
    names.split(',').any(|n| n == name)
}

/// A varint at `*p` in DATA.
fn varint(p: &mut usize) -> u32 {
    varint_in(&DATA, p)
}

fn varint_in(bytes: &[u8], p: &mut usize) -> u32 {
    let mut v = 0;
    let mut shift = 0;
    loop {
        let b = bytes[*p];
        *p += 1;
        v |= ((b & 0x7F) as u32) << shift;
        if b < 0x80 {
            return v;
        }
        shift += 7;
    }
}

fn decode_set(off: u32) -> Vec<(u32, u32)> {
    let mut p = off as usize;
    let n = varint(&mut p);
    let mut out = crate::buf::vec_with_capacity(n as usize);
    let mut prev = 0;
    for _ in 0..n {
        let lo = prev + varint(&mut p);
        let hi = lo + varint(&mut p);
        out.push_out((lo, hi));
        prev = hi + 1;
    }
    out
}

fn decode_sequences(off: u32) -> Vec<Vec<u32>> {
    let mut p = off as usize;
    let n = varint(&mut p);
    let mut out: Vec<Vec<u32>> = crate::buf::vec_with_capacity(n as usize);
    for _ in 0..n {
        let prefix = varint(&mut p) as usize;
        let len = varint(&mut p);
        let mut s: Vec<u32> = match out.last() {
            Some(prev) => prev[..prefix].to_vec(),
            None => Vec::new(),
        };
        let mut last = s.last().copied().unwrap_or(0);
        for _ in 0..len {
            let z = varint(&mut p);
            let d = if z & 1 == 0 {
                (z >> 1) as i64
            } else {
                -(((z + 1) >> 1) as i64)
            };
            last = (last as i64 + d) as u32;
            s.push_out(last);
        }
        out.push_out(s);
    }
    out
}

/// The ZWJ sequences of the templates at `off` (scripts/gen-unicode.py `encode_zwj`, D2334):
/// each template with its modifier and hair slots filled in every way its code says.
fn decode_zwj(off: u32) -> Vec<Vec<u32>> {
    const MODIFIER: u32 = 0x1F3FB;
    const HAIR: u32 = 0x1F9B0;
    // Slot markers in a template; real code points are never this large.
    const MOD_SLOT: u32 = u32::MAX;
    const HAIR_SLOT: u32 = u32::MAX - 1;
    let mut p = off as usize;
    let n = varint(&mut p);
    let mut out = Vec::new();
    let mut sk: Vec<u32> = Vec::new();
    for _ in 0..n {
        let prefix = varint(&mut p) as usize;
        let len = varint(&mut p);
        let code = DATA[p];
        p += 1;
        sk.truncate(prefix);
        // Deltas continue from the last real code point of the shared prefix.
        let mut last = 0;
        for &c in &sk {
            if c < HAIR_SLOT && c != 0x200D && c != 0xFE0F {
                last = c;
            }
        }
        for _ in 0..len {
            let t = varint(&mut p);
            sk.push_out(match t {
                0 => MOD_SLOT,
                1 => HAIR_SLOT,
                2 => 0x200D,
                3 => 0xFE0F,
                z => {
                    let z = z - 4;
                    let d = if z & 1 == 0 {
                        (z >> 1) as i64
                    } else {
                        -(((z + 1) >> 1) as i64)
                    };
                    last = (last as i64 + d) as u32;
                    last
                }
            });
        }
        let hairs = if code & 4 != 0 { 4 } else { 1 };
        for h in 0..hairs {
            for a in 0..5 {
                for b in 0..5 {
                    let keep = match code & 3 {
                        0 => a == 0 && b == 0,
                        1 => b == 0,
                        2 => true,
                        _ => a != b,
                    };
                    if !keep {
                        continue;
                    }
                    let mut seq = crate::buf::vec_with_capacity(sk.len());
                    let mut first = true;
                    for &c in &sk {
                        seq.push_out(match c {
                            MOD_SLOT => {
                                let t = if first { a } else { b };
                                first = false;
                                MODIFIER + t
                            }
                            HAIR_SLOT => HAIR + h,
                            c => c,
                        });
                    }
                    out.push_out(seq);
                }
            }
        }
    }
    out
}

/// The code points whose General_Category is one of `mask`'s leaves (bit i:
/// `GENERAL_CATEGORY[i]`), from the partition in GC_RUNS (D2334).
fn gc_set(mask: u32) -> Vec<(u32, u32)> {
    let mut out: Vec<(u32, u32)> = Vec::new();
    if mask == 0 {
        return out;
    }
    let mut c = 0u32;
    let mut p = 0;
    while p < GC_RUNS.len() {
        let b = GC_RUNS[p];
        p += 1;
        let mut n = (b >> 5) as u32;
        if n == 7 {
            n += varint_in(&GC_RUNS, &mut p);
        }
        if mask >> (b & 31) & 1 != 0 {
            match out.last_mut() {
                Some(last) if last.1 + 1 == c => last.1 = c + n - 1,
                _ => out.push_out((c, c + n - 1)),
            }
        }
        c += n;
    }
    out
}

/// The union of sorted range lists.
fn union(mut a: Vec<(u32, u32)>, b: &[(u32, u32)]) -> Vec<(u32, u32)> {
    a.extend_from_slice(b);
    normalize(a)
}

/// Sorts and merges overlapping or adjacent ranges.
fn normalize(mut v: Vec<(u32, u32)>) -> Vec<(u32, u32)> {
    crate::sort::sort_by(&mut v, |x, y| x.0 < y.0);
    let mut out: Vec<(u32, u32)> = crate::buf::vec_with_capacity(v.len());
    for (lo, hi) in v {
        match out.last_mut() {
            Some(last) if lo <= last.1.saturating_add(1) => last.1 = last.1.max(hi),
            _ => out.push_out((lo, hi)),
        }
    }
    out
}

/// `a` minus `b`.
fn subtract(a: &[(u32, u32)], b: &[(u32, u32)]) -> Vec<(u32, u32)> {
    let mut out = Vec::new();
    let mut j = 0;
    for &(lo, hi) in a {
        let mut lo = lo;
        while j < b.len() && b[j].1 < lo {
            j += 1;
        }
        let mut k = j;
        while lo <= hi {
            if k >= b.len() || b[k].0 > hi {
                out.push_out((lo, hi));
                break;
            }
            if b[k].0 > lo {
                out.push_out((lo, b[k].0 - 1));
            }
            if b[k].1 >= hi {
                break;
            }
            lo = b[k].1 + 1;
            k += 1;
        }
    }
    out
}

fn general_category(value: &str) -> Option<Vec<(u32, u32)>> {
    if let Some(i) = GENERAL_CATEGORY.iter().position(|n| has_name(n, value)) {
        return Some(gc_set(1 << i));
    }
    let &(_, mask) = GENERAL_CATEGORY_GROUPS
        .iter()
        .find(|(n, _)| has_name(n, value))?;
    Some(gc_set(mask))
}

fn script(value: &str, extensions: bool) -> Option<Vec<(u32, u32)>> {
    let &(_, sc, scx) = SCRIPTS.iter().find(|(n, _, _)| has_name(n, value))?;
    let base = decode_set(sc);
    if !extensions {
        return Some(base);
    }
    // Code points listed in ScriptExtensions.txt have exactly the scripts listed there.
    let mut out = subtract(&base, &decode_set(SCX_EXPLICIT));
    if scx != u32::MAX {
        out = union(out, &decode_set(scx));
    }
    Some(out)
}

fn binary(name: &str) -> Option<Vec<(u32, u32)>> {
    match name {
        "Any" => return Some(alloc::vec![(0, 0x10FFFF)]),
        "ASCII" => return Some(alloc::vec![(0, 0x7F)]),
        "Assigned" => {
            let cn = GENERAL_CATEGORY.iter().position(|n| has_name(n, "Cn"))?;
            return Some(gc_set(((1 << GENERAL_CATEGORY.len()) - 1) & !(1 << cn)));
        }
        _ => {}
    }
    let i = BINARY.iter().position(|(n, _)| has_name(n, name))?;
    Some(binary_set(i))
}

/// Binary property `i`: its base (a union of General_Category leaves and maybe an earlier
/// property) XOR the stored difference (D2334).
fn binary_set(i: usize) -> Vec<(u32, u32)> {
    let mut p = BINARY[i].1 as usize;
    let mask = varint(&mut p);
    let earlier = varint(&mut p) as usize;
    let mut base = gc_set(mask);
    if earlier != 0 {
        base = union(base, &binary_set(earlier - 1));
    }
    let diff = decode_set(p as u32);
    union(subtract(&base, &diff), &subtract(&diff, &base))
}

/// The sequences of a property of strings, by the coding `kind` (D2334). In no particular
/// order: the regexp compiler orders class strings itself.
fn decode_strings(off: u32, kind: u8) -> Vec<Vec<u32>> {
    if kind == 4 {
        return decode_zwj(off);
    }
    if kind == 0 {
        return decode_sequences(off);
    }
    let mut out = Vec::new();
    for (lo, hi) in decode_set(off) {
        for c in lo..=hi {
            match kind {
                1 => out.push_out(alloc::vec![c, 0xFE0F]),
                2 => {
                    for m in 0x1F3FB..0x1F400 {
                        out.push_out(alloc::vec![c, m]);
                    }
                }
                _ => out.push_out(alloc::vec![0x1F1E6 + c / 26, 0x1F1E6 + c % 26]),
            }
        }
    }
    out
}

fn string_property(name: &str) -> Option<Property> {
    if name == "RGI_Emoji" {
        let mut all = Property::default();
        for &(_, chars, seqs, kind) in &STRINGS {
            all.ranges = union(all.ranges, &decode_set(chars));
            all.strings.extend(decode_strings(seqs, kind));
        }
        return Some(all);
    }
    let &(_, chars, seqs, kind) = STRINGS.iter().find(|(n, _, _, _)| *n == name)?;
    Some(Property {
        ranges: decode_set(chars),
        strings: decode_strings(seqs, kind),
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    fn contains(p: &Property, c: u32) -> bool {
        p.ranges.iter().any(|&(lo, hi)| lo <= c && c <= hi)
    }

    #[test]
    fn lookups() {
        let lu = lookup("Lu", "", false).unwrap();
        assert!(contains(&lu, 'A' as u32) && !contains(&lu, 'a' as u32));
        let l = lookup("gc", "Letter", false).unwrap();
        assert!(contains(&l, 'a' as u32) && contains(&l, 0x4E00) && !contains(&l, '1' as u32));
        let greek = lookup("Script", "Greek", false).unwrap();
        assert!(contains(&greek, 0x3B1) && !contains(&greek, 0x342));
        let greek_x = lookup("scx", "Grek", false).unwrap();
        assert!(contains(&greek_x, 0x342));
        let assigned = lookup("Assigned", "", false).unwrap();
        assert!(contains(&assigned, 'a' as u32) && !contains(&assigned, 0x378));
        assert!(contains(&lookup("space", "", false).unwrap(), ' ' as u32));
        assert_eq!(lookup("WSpace", "", false), Err(PropertyError::Name));
        assert_eq!(lookup("lu", "", false), Err(PropertyError::Name));
        assert_eq!(lookup("Script", "Foo", false), Err(PropertyError::Script));
        assert_eq!(
            lookup("General_Category", "", false),
            Err(PropertyError::GeneralCategory)
        );
        assert_eq!(lookup("RGI_Emoji", "", false), Err(PropertyError::Name));
        let flags = lookup("RGI_Emoji_Flag_Sequence", "", true).unwrap();
        assert!(flags.strings.contains(&alloc::vec![0x1F1E9, 0x1F1EA]));
        let rgi = lookup("RGI_Emoji", "", true).unwrap();
        assert!(contains(&rgi, 0x1F600));
        assert!(
            rgi.strings
                .contains(&alloc::vec![0x1F468, 0x200D, 0x1F469, 0x200D, 0x1F467])
        );
    }

    #[test]
    fn subtract_ranges() {
        assert_eq!(
            subtract(&[(0, 10), (20, 30)], &[(2, 3), (5, 25)]),
            alloc::vec![(0, 1), (4, 4), (26, 30)]
        );
        assert_eq!(subtract(&[(0, 10)], &[]), alloc::vec![(0, 10)]);
        assert_eq!(subtract(&[(5, 6)], &[(0, 10)]), alloc::vec![]);
    }
}
